#include <iostream>
using namespace std;

int main() {
    int obstacle;
    cin >> obstacle;

    for (int sector = 1; sector <= 5; sector++) {
        if (sector == obstacle) {
            cout << "OBSTACLE AT SECTOR " << sector << endl;
            break;
        } else {
            cout << "SECTOR " << sector << " CLEARED" << endl;
        }
    }
    cout << "PATROL ENDED" << endl;

    return 0;
}

