#include <iostream>
using namespace std;

int main() {
    int target;
    cin >> target;

    for (int freq = 100; freq <= 104; freq++) {
        if (freq == target) {
            cout << "BEACON FOUND AT " << freq << endl;
            break;
        } else {
            cout << "SEARCHING " << freq << endl;
        }
    }
    cout << "SEARCH SEQUENCE FINISHED" << endl;

    return 0;
}
